import numpy as np
from scipy import stats

MAX_DRIVERS = 4

def design(feats):
    # Identify potential drivers using t-statistics and correlation filtering
    ids = feats.ids
    types = feats.types
    x = feats.x
    y = feats.y

    # Calculate t-statistics for each feature
    t_stats = []
    for i, fid in enumerate(ids):
        x1 = x[y==1, i]
        x0 = x[y==0, i]
        if len(x1) > 1 and len(x0) > 1:
            t, _ = stats.ttest_ind(x1, x0, equal_var=False)
        else:
            t = 0
        t_stats.append(abs(t))

    # Sort by absolute t-statistic
    sorted_idx = np.argsort(t_stats)[::-1]
    candidates = [ids[i] for i in sorted_idx]

    # Remove near-duplicates based on correlations
    keep = []
    correlated_pairs = set()

    # Check for strong correlations (|r| >= 0.6)
    for i in range(len(ids)):
        for j in range(i+1, len(ids)):
            corr = np.corrcoef(x[:,i], x[:,j])[0,1]
            if abs(corr) >= 0.6:
                correlated_pairs.add((ids[i], ids[j]))

    # Filter out correlated features, keeping only one from each pair
    used = set()
    for fid in candidates:
        if fid in used:
            continue
        keep.append(fid)
        used.add(fid)
        # Also mark correlated features as used
        for other_fid, corr_fid in correlated_pairs:
            if other_fid == fid:
                used.add(corr_fid)
            elif corr_fid == fid:
                used.add(other_fid)

    # Limit to MAX_DRIVERS
    drivers = tuple(keep[:MAX_DRIVERS])

    # For columns, use all features with significant t-stats
    columns = tuple([fid for i, fid in enumerate(ids) 
                     if t_stats[i] > 1.5])

    # For products, look for interactions between top features
    products = []
    top_features = list(columns)[:10]  # Top 10 features for interaction search

    # Simple approach: check pairwise products of top features
    for i in range(len(top_features)):
        for j in range(i+1, len(top_features)):
            a, b = top_features[i], top_features[j]
            if a != b:
                products.append((a, b))

    # Create loadings dictionary for weighted score
    loadings = {}
    for i, fid in enumerate(ids):
        if t_stats[i] > 1.5:
            loadings[fid] = t_stats[i]

    return Design(
        drivers=drivers,
        columns=columns,
        products=tuple(products),
        loadings=loadings
    )
